WFJ.Data.add("quest", {
  [89001] = { "草原の我が家", "Mosshoof Hideを5枚、AzsharaのTalrendis PointにいるBerdun Cliffbrewのところへ持って行ってください。", "ようこそ、旅の人！\n\n帽子を掛ける場所を探しとるなら、Berdunの旅の宿で決まりだ！テントは今ちょいと傷んどるが、そいつは直せる。\n\nこうしよう。テントを直すのに要るもんを持ってきてくれたら、ただでここに泊めてやる。どうだ？\n\nmosshoof hidesが要るんだ。一番狩りやすいmosshoovesはここからすぐ北にいるが、どのmooshoofの皮でも構わん。", nil, nil, 0x92b07f24, 0x8e189fa2, 0xd9ae32b5, nil, nil, "...mm" },
  [89013] = { "ほろ酔い気分", "Berdun's Pellet Gunを使い、Wasp NestsからWild Honeyを$N1個集めてください。", "飲み物のない旅の宿なんて、なんの意味がある？\n\nうまい蜂蜜酒なら醸せるが、自分で蜂蜜を集めるにはちと歳を取りすぎた。Haldaarの野営地の北と、Valormokの西の木々にスズメバチの巣がある。ヒッポグリフが見えたら、そこが正しい場所だ。\n\n厄介な奴らだが、蜂蜜は今まで味わったことのないうまさだ。巣を撃ち落とせるように、わしのペレット銃を貸してやろう。そうでもせんと届かんからな。", nil, nil, 0x1c810d6b, 0x3da1e6f4, 0x7a20f406, nil, nil, "...mm" },
  [89015] = { "最も危険な漁", "Mammoth Shark SteakをAzsharaのTalrendis PointにいるBerdun Cliffbrewのところへ持って行ってください。", "自分が本物の釣り人だと思っとるなら、ここには竿じゃ釣れんでかい魚がおるぞ。\n\nMammoth Sharksは北と南の海岸の一番深い海に潜んどる。奴らはずっと沖まで泳いでいく。海底が大海へとがくんと落ち込む手前までな。\n\nとんでもなくでかいからな。釣り人仲間を何人か連れていくことを勧めるぞ。\n\nわしのようなドワーフか？わしは乾いた陸のほうが好きだ。あのサメどもなら、わしを一口で飲み込んじまう。\n\n一匹狩りに行くなら、その肉をひと切れ持ってきてくれ。とても感謝するぞ。", nil, nil, 0xb3dfd878, 0x3c6a73c3, 0x18179217, nil, nil, "...mm" },
  [89037] = { "Murlocの泥棒", "Tower of Eldara付近にいるRazorgillからMemory Crystalを奪い、AzsharaにいるSaria Fairmoonのところへ持って行ってください。", "ここから東、北の半島の浜辺で、Tower of Eldaraを見つけた。現地を調べていると、大きなオレンジ色のmurlocがトゲ付きの棍棒を振り回し、奇妙な光る水晶を持っているのに気づいた。場所を考えると、highborneが自分たちの歴史や記憶を保存するのに使っていた類のものだろう。\n\nその水晶を取り戻さねばならない、{race}。どんな秘密が秘められているかわからないぞ。\n\n塔への一番の道は崖沿いで、一番近い登り口はここからすぐ西だ。", nil, nil, 0x6e48aaeb, 0x6011f7da, 0x917279fa, nil, nil, "...mm" },
  [89038] = { "途方もない仕事", "Ravencrest Monumentの遺跡の中からMark of the Queenを探し出し、AzsharaにいるSaria Fairmoonのところへ持って行ってください。", "かつてQueen Azsharaは、House Ravencrestのkaldoreiに贈り物を授けたという。偉大な美しさと魔力を備えた紋章だ。この印は、女王に対するRavencrest家の揺るぎない忠誠を称えて与えられた。\n\nその印が最後に目撃されたのは、南の半島の崖の上にあるRavencrest Monumentの近くだ。そのような遺物を確保できれば、一生に一度の大発見になるだろう。\n\nいつものように、記念碑の廃墟にはSpitelashがうようよしているが、君ならもう奴らの扱いにはかなり慣れていると信じているよ。", nil, nil, 0x4ac1a9f7, 0x6552fb2f, 0x3fbc7528, nil, nil, "...mm" },
  [89053] = { "最後の報酬", "Sariaが見せたいものを見てください。", "君がもともと偵察のためにここへ送られてきたのは知っている、{name}。だが、君は考古学の分野に大いに貢献してくれた。\n\nこれだけ苦労してきたんだ、私の研究がどんな実を結ぶのか、きっと知りたいだろう。\n\nそこで、君が野営地へ戻る前に、見せたいものがあるんだ。付き合ってくれるかい？", nil, nil, 0xa81ff7ad, 0x1871f749, 0x18765a13, nil, nil, "...mm" },
  [89228] = { "Winter Frontier Fishery", "AzsharaのTalrendis PointにいるBerdun Cliffbrewのために、Winter Squidを10匹釣り上げてください。", "まともな旅の宿なら、食い物がなきゃ話にならん。\n\nイカが旬でな、ここAzsharaの海岸で釣り上げられる。わし自身は大した釣り人じゃなかったが、料理の腕は確かだ！\n\nどうだ？海の幸を食いたい気分か？\n\n釣りが得意じゃないなら、釣り人と友達になってみな！それか、そいつらに金を払って買うといい。", nil, nil, 0x3c26918f, 0xb267266a, 0xf53297d7, nil, nil, "...mm" },
  [89381] = { "針山", "New Avalonの町の広場の南にある射撃場で矢を集める。レンジャーと戦って矢を手に入れることもできる。", "おっと！訓練の真っ最中に射撃場をうろつくなんて、ずいぶん度胸があるじゃないか。膝に矢を受けたいって言ってるようなもんだぞ。いや、そのもたもたした歩き方じゃ、尻にかもしれないな。\n\nでもまあ、自分の身の安全はあんたの勝手だ。見たところ相当な命知らずみたいだし、ちょっと手を貸してくれないか？射撃のたびに矢を集めてたら、貴重な射撃の時間が削られちまうんだ。\n\n何本か拾ってきてくれないか、な？", nil, nil, 0xe16773a5, 0x704c15f3, 0x61a7db97, nil, nil, "...mm" },
  [89463] = { "守秘義務の口論", "New AvalonのFizzlefuseが、羽根ペンと、隠れ家をもっと快適にするための何かを求めています。Classy QuillはNew Avalon Town Hallで見つかり、House PropはScholomanceの近くかKarazhan Cryptsのどこかで見つかるかもしれない。", "私は自分の秘密をどこの馬の骨とも知れない冒険者に教えるようなゴブリンじゃないが、ノームの秘密なら喜んで教えるタイプだ！ここへ来る途中でいくつか設計図を手に入れてね、その設計の欠点を直しているところなんだ。あいつら、いまだに安全ヒューズなんか使ってるんだぞ！信じられるか？安全ヒューズだ！！\n\nとにかく、進み具合を早く見せたいんだが、このガラクタを全部書き出すには羽ペンが要る。それに、じっくり考え事ができる居心地のいい場所も欲しい。どうだい？", nil, nil, 0x71d0c0b4, 0xc62fcb00, 0x395b3f3b, nil, nil, "...mm" },
  [89470] = { "悪い知らせ", "Saria's KnapsackをTalrendis PointにいるCommander Truesongのところへ持って帰ってください。", "<Sariaの真の意図が明らかになり、強力な遺物の入った鞄も手に入れた。そろそろCommander Truesongに報告をする頃合いだろう。>", nil, nil, 0xc03d012c, 0xef218594, 0x4d6309d5, nil, nil, "...mm" },
